package dev.veltraph.client.galatea.workflow;

import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GalateaSourceTravelCycleTest {
    private final Object player=new Object(),world=new Object(),connection=new Object();
    private final GalateaSourceTravelCycle cycle=new GalateaSourceTravelCycle();
    private final class Port implements GalateaSourceTravelCycle.Actions {int sends,releases;boolean allowed=true;public boolean send(String c){sends++;return allowed;}public void release(){releases++;}}
    private final Port port=new Port();
    private GalateaSourceTravelCycle.Profile profile(){return new GalateaSourceTravelCycle.Profile(GalateaSourceTravelCycle.Kind.MURKWATER,true,"/explicit_test_route","exact route arrival","exact route rejected","minecraft:overworld",GalateaSourceTravelCycle.MURKWATER,10000);}
    private GalateaSourceTravelCycle.Observation observation(Vec3 p,long tick,long serial,Vec3 teleport,boolean receipt,boolean supported,long now){return new GalateaSourceTravelCycle.Observation(true,player,world,connection,"minecraft:overworld",p,supported,tick,serial,teleport,receipt,false,now);}
    private boolean start(){return cycle.start(profile(),observation(GalateaSourceTravelCycle.MARSH,10,1,null,false,true,100),port);}
    private GalateaSourceTravelCycle.State arrival(long tick,long now){return cycle.tick(profile(),observation(GalateaSourceTravelCycle.MURKWATER,tick,2,GalateaSourceTravelCycle.MURKWATER,true,true,now),port);}
    @Test void exactConstants(){assertEquals(new Vec3(-548,109,-23),GalateaSourceTravelCycle.MARSH);assertEquals(new Vec3(-645,90,2),GalateaSourceTravelCycle.MURKWATER);}
    @Test void sourceMarshStrictThreshold(){assertFalse(cycle.start(profile(),observation(new Vec3(-528,109,-23),10,1,null,false,true,100),port));assertEquals(0,port.sends);}
    @Test void sourceMarshNearThreshold(){assertTrue(cycle.start(profile(),observation(new Vec3(-528.01,109,-23),10,1,null,false,true,100),port));}
    @Test void blankUnknownMetadataCannotDispatch(){var p=profile();assertFalse(cycle.start(new GalateaSourceTravelCycle.Profile(p.kind(),true,"",p.receipt(),p.rejection(),p.dimension(),p.destination(),p.timeout()),observation(GalateaSourceTravelCycle.MARSH,10,1,null,false,true,100),port));assertEquals(0,port.sends);}
    @Test void noPermissionCannotDispatch(){var p=profile();assertFalse(GalateaSourceTravelCycle.valid(new GalateaSourceTravelCycle.Profile(p.kind(),false,p.command(),p.receipt(),p.rejection(),p.dimension(),p.destination(),p.timeout())));}
    @Test void nativeReceiptAndThreeDistinctTicks(){assertTrue(start());assertEquals(GalateaSourceTravelCycle.State.WAITING,arrival(11,150));assertEquals(GalateaSourceTravelCycle.State.WAITING,arrival(11,160));assertEquals(GalateaSourceTravelCycle.State.WAITING,arrival(12,200));assertEquals(GalateaSourceTravelCycle.State.COMPLETE,arrival(13,250));assertEquals(1,port.sends);}
    @Test void positionAndSuccessTextWithoutFreshPacketDoNotComplete(){assertTrue(start());for(int i=11;i<20;i++)assertEquals(GalateaSourceTravelCycle.State.WAITING,cycle.tick(profile(),observation(GalateaSourceTravelCycle.MURKWATER,i,1,null,true,true,100+i*50),port));}
    @Test void nativePacketWithoutExactServerReceiptDoesNotComplete(){assertTrue(start());for(int i=11;i<20;i++)assertEquals(GalateaSourceTravelCycle.State.WAITING,cycle.tick(profile(),observation(GalateaSourceTravelCycle.MURKWATER,i,2,GalateaSourceTravelCycle.MURKWATER,false,true,100+i*50),port));}
    @Test void murkwaterStrictThreshold(){assertTrue(start());Vec3 outside=new Vec3(-640,90,2);assertEquals(GalateaSourceTravelCycle.State.FAILED,cycle.tick(profile(),observation(outside,11,2,outside,true,true,150),port));}
    @Test void ungroundedTickResetsSupportWindow(){assertTrue(start());arrival(11,150);arrival(12,200);cycle.tick(profile(),observation(GalateaSourceTravelCycle.MURKWATER,13,2,GalateaSourceTravelCycle.MURKWATER,true,false,250),port);assertEquals(GalateaSourceTravelCycle.State.WAITING,arrival(14,300));assertEquals(GalateaSourceTravelCycle.State.WAITING,arrival(15,350));assertEquals(GalateaSourceTravelCycle.State.COMPLETE,arrival(16,400));}
    @Test void unknownOutcomeTimeoutNeverRetries(){assertTrue(start());assertEquals(GalateaSourceTravelCycle.State.FAILED,arrival(11,10100));arrival(12,10200);assertEquals(1,port.sends);}
    @Test void ownerChangeCancels(){assertTrue(start());var o=observation(GalateaSourceTravelCycle.MURKWATER,11,2,GalateaSourceTravelCycle.MURKWATER,true,true,150);assertEquals(GalateaSourceTravelCycle.State.CANCELLED,cycle.tick(profile(),new GalateaSourceTravelCycle.Observation(true,new Object(),o.world(),o.connection(),o.dimension(),o.position(),true,11,2,o.teleport(),true,false,150),port));assertEquals(1,port.sends);}
    @Test void profileChangeCancels(){assertTrue(start());var p=profile();assertEquals(GalateaSourceTravelCycle.State.CANCELLED,cycle.tick(new GalateaSourceTravelCycle.Profile(p.kind(),p.permission(),"/other",p.receipt(),p.rejection(),p.dimension(),p.destination(),p.timeout()),observation(GalateaSourceTravelCycle.MURKWATER,11,2,GalateaSourceTravelCycle.MURKWATER,true,true,150),port));}
    @Test void explicitServerRejectionFails(){assertTrue(start());var o=observation(GalateaSourceTravelCycle.MURKWATER,11,2,GalateaSourceTravelCycle.MURKWATER,true,true,150);assertEquals(GalateaSourceTravelCycle.State.FAILED,cycle.tick(profile(),new GalateaSourceTravelCycle.Observation(o.healthy(),o.player(),o.world(),o.connection(),o.dimension(),o.position(),o.supported(),o.nativeTick(),o.serial(),o.teleport(),true,true,o.now()),port));}
    @Test void expectedTeleportIsFreshOwnedAndConsumedOnce(){assertTrue(start());var o=observation(GalateaSourceTravelCycle.MURKWATER,11,2,GalateaSourceTravelCycle.MURKWATER,true,true,150);assertTrue(cycle.consumeExpectedTeleport(o,o.position(),150));assertFalse(cycle.consumeExpectedTeleport(o,o.position(),151));}
    @Test void cancelAndDispatchRefusalDoNotRetry(){assertTrue(start());cycle.cancel(port);arrival(11,150);assertEquals(GalateaSourceTravelCycle.State.CANCELLED,cycle.state());assertEquals(1,port.sends);port.allowed=false;assertFalse(start());assertEquals(GalateaSourceTravelCycle.State.FAILED,cycle.state());assertEquals(2,port.sends);}
    @Test void resetUsesExplicitDestinationWithoutInventingMarshAdmission(){var p=new GalateaSourceTravelCycle.Profile(GalateaSourceTravelCycle.Kind.RESET,true,"/explicit_reset","reset arrived","reset rejected","minecraft:overworld",new Vec3(4,70,8),10000);assertTrue(cycle.start(p,observation(new Vec3(1,70,1),10,1,null,false,true,100),port));for(int tick=11;tick<=13;tick++)cycle.tick(p,observation(p.destination(),tick,2,p.destination(),true,true,100+tick*50),port);assertEquals(GalateaSourceTravelCycle.State.COMPLETE,cycle.state());assertEquals(1,port.sends);}
    @Test void unsupportedAdmissionNeverSends(){assertFalse(cycle.start(profile(),observation(GalateaSourceTravelCycle.MARSH,10,1,null,false,false,100),port));assertEquals(0,port.sends);}
    @Test void commandControlCharactersRefused(){assertFalse(GalateaSourceTravelCycle.commandSafe("/warp\nother"));assertFalse(GalateaSourceTravelCycle.commandSafe("//warp"));assertFalse(GalateaSourceTravelCycle.commandSafe("warp"));}
}
